// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "c_otherwise_57", fn: function(){ return (!((1==1) || (1==2) || (1==3) || (1==4))); } }, { id: "c_otherwise_81", fn: function(){ return (!((1>=4))); } }, { id: "c_otherwise_57_r1", fn: function(){ return (!((2==1) || (2==2) || (2==3) || (2==4))); } }, { id: "c_otherwise_81_r1", fn: function(){ return (!((2>=4))); } }, { id: "c_otherwise_57_r2", fn: function(){ return (!((3==1) || (3==2) || (3==3) || (3==4))); } }, { id: "c_otherwise_81_r2", fn: function(){ return (!((3>=4))); } }, { id: "c_otherwise_57_r3", fn: function(){ return (!((4==1) || (4==2) || (4==3) || (4==4))); } }, { id: "c_otherwise_81_r3", fn: function(){ return (!((4>=4))); } }, { id: "c_otherwise_57_r4", fn: function(){ return (!((5==1) || (5==2) || (5==3) || (5==4))); } }, { id: "c_otherwise_81_r4", fn: function(){ return (!((5>=4))); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.initValue();
        scwin.chkChrgDesignReadonly();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil25113.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil25113.onpageload' });
    }
};


